// Convierte los adjuntos (binarios) en lotes de hasta 5 documentos para Nokfi.
const TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const docs = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if (!TYPES.includes(bin.mimeType)) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    docs.push({ name: bin.fileName || key, mime: bin.mimeType, data: buffer.toString('base64') });
  }
}
const batches = [];
for (let k = 0; k < docs.length; k += 5) batches.push({ json: { files: docs.slice(k, k + 5) } });
return batches;

// Una fila por factura, con las comprobaciones de Nokfi en columnas.
const rows = [];
for (const item of $input.all()) {
  for (const inv of item.json.invoices || []) {
    rows.push({ json: {
      archivo: inv.file_name, emisor: inv.issuer_name, nif_emisor: inv.issuer_nif,
      numero: inv.invoice_number, fecha: inv.invoice_date, vencimiento: inv.due_date,
      base: inv.base, tipo_iva: inv.vat_rate, iva: inv.vat_amount, retencion: inv.irpf_amount, total: inv.total,
      cuadra: inv.checks.totals_ok ? 'sí' : 'NO', nif_valido: inv.checks.nif_valid ? 'sí' : 'NO',
      avisos: (inv.warnings || []).map(w => w.message).join(' · ')
    } });
  }
}
return rows;
